    53→// DetectPresence checks if Gemini CLI is configured in the repository.
    54→func (g *GeminiCLIAgent) DetectPresence(ctx context.Context) (bool, error) {
    55→	// Get worktree root to check for .gemini directory
    56→	// This is needed because the CLI may be run from a subdirectory
    57→	repoRoot, err := paths.WorktreeRoot(ctx)
    58→	if err != nil {
    59→		// Not in a git repo, fall back to CWD-relative check
    60→		repoRoot = "."
    61→	}
    62→
    63→	// Check for .gemini directory
    64→	geminiDir := filepath.Join(repoRoot, ".gemini")
    65→	if _, err := os.Stat(geminiDir); err == nil {
    66→		return true, nil
    67→	}
    68→	// Check for .gemini/settings.json
    69→	settingsFile := filepath.Join(repoRoot, ".gemini", "settings.json")
    70→	if _, err := os.Stat(settingsFile); err == nil {
    71→		return true, nil
    72→	}
    73→	return false, nil
    74→}
