   126→// ReadSession reads a session from Gemini's storage (JSON transcript file).
   127→// The session data is stored in NativeData as raw JSON bytes.
   128→func (g *GeminiCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
   129→	if input.SessionRef == "" {
   130→		return nil, errors.New("session reference (transcript path) is required")
   131→	}
   132→
   133→	// Read the raw JSON file
   134→	data, err := os.ReadFile(input.SessionRef)
   135→	if err != nil {
   136→		return nil, fmt.Errorf("failed to read transcript: %w", err)
   137→	}
   138→
   139→	// Parse to extract computed fields
   140→	modifiedFiles, err := ExtractModifiedFiles(data)
   141→	if err != nil {
   142→		// Non-fatal: we can still return the session without modified files
   143→		modifiedFiles = nil
   144→	}
   145→
   146→	return &agent.AgentSession{
   147→		SessionID:     input.SessionID,
   148→		AgentName:     g.Name(),
   149→		SessionRef:    input.SessionRef,
   150→		StartTime:     time.Now(),
   151→		NativeData:    data,
   152→		ModifiedFiles: modifiedFiles,
   153→	}, nil
   154→}
