   156→// WriteSession writes a session to Gemini's storage (JSON transcript file).
   157→// Uses the NativeData field which contains raw JSON bytes.
   158→func (g *GeminiCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
   159→	if session == nil {
   160→		return errors.New("session is nil")
   161→	}
   162→
   163→	// Verify this session belongs to Gemini CLI
   164→	if session.AgentName != "" && session.AgentName != g.Name() {
   165→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
   166→	}
   167→
   168→	if session.SessionRef == "" {
   169→		return errors.New("session reference (transcript path) is required")
   170→	}
   171→
   172→	if len(session.NativeData) == 0 {
   173→		return errors.New("session has no native data to write")
   174→	}
   175→
   176→	// Write the raw JSON data
   177→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
   178→		return fmt.Errorf("failed to write transcript: %w", err)
   179→	}
   180→
   181→	return nil
   182→}
