   214→func TestInstallHooks_PreservesUnknownHookTypes(t *testing.T) {
   215→	tempDir := t.TempDir()
   216→	t.Chdir(tempDir)
   217→
   218→	// Create settings with hook types we don't handle (hypothetical future Gemini hook types)
   219→	writeGeminiSettings(t, tempDir, `{
   220→  "hooks": {
   221→    "FutureHook": [
   222→      {
   223→        "matcher": "",
   224→        "hooks": [{"name": "future-hook", "type": "command", "command": "echo future"}]
   225→      }
   226→    ],
   227→    "AnotherNewHook": [
   228→      {
   229→        "matcher": "pattern",
   230→        "hooks": [{"name": "another-hook", "type": "command", "command": "echo another"}]
   231→      }
   232→    ]
   233→  }
   234→}`)
   235→
   236→	agent := &GeminiCLIAgent{}
   237→	_, err := agent.InstallHooks(context.Background(), false, false)
   238→	if err != nil {
   239→		t.Fatalf("InstallHooks() error = %v", err)
   240→	}
   241→
   242→	// Read raw hooks to verify unknown hook types are preserved
   243→	rawHooks := testutil.ReadRawHooks(t, tempDir, ".gemini")
   244→
   245→	// Verify FutureHook is preserved
   246→	if _, ok := rawHooks["FutureHook"]; !ok {
   247→		t.Errorf("FutureHook type was not preserved, got keys: %v", testutil.GetKeys(rawHooks))
   248→	}
   249→
   250→	// Verify AnotherNewHook is preserved
   251→	if _, ok := rawHooks["AnotherNewHook"]; !ok {
   252→		t.Errorf("AnotherNewHook type was not preserved, got keys: %v", testutil.GetKeys(rawHooks))
   253→	}
   254→
   255→	// Verify the FutureHook content is intact
   256→	var futureMatchers []GeminiHookMatcher
   257→	if err := json.Unmarshal(rawHooks["FutureHook"], &futureMatchers); err != nil {
   258→		t.Fatalf("failed to parse FutureHook: %v", err)
   259→	}
   260→	if len(futureMatchers) != 1 {
   261→		t.Errorf("FutureHook matchers = %d, want 1", len(futureMatchers))
   262→	}
   263→	if len(futureMatchers) > 0 && len(futureMatchers[0].Hooks) > 0 {
   264→		if futureMatchers[0].Hooks[0].Command != "echo future" {
   265→			t.Errorf("FutureHook command = %q, want %q",
   266→				futureMatchers[0].Hooks[0].Command, "echo future")
   267→		}
   268→	}
   269→
   270→	// Verify AnotherNewHook content including matcher
   271→	var anotherMatchers []GeminiHookMatcher
   272→	if err := json.Unmarshal(rawHooks["AnotherNewHook"], &anotherMatchers); err != nil {
   273→		t.Fatalf("failed to parse AnotherNewHook: %v", err)
   274→	}
   275→	if len(anotherMatchers) > 0 {
   276→		if anotherMatchers[0].Matcher != "pattern" {
   277→			t.Errorf("AnotherNewHook matcher = %q, want %q", anotherMatchers[0].Matcher, "pattern")
   278→		}
   279→	}
   280→
   281→	// Verify our hooks were also installed
   282→	if _, ok := rawHooks["SessionStart"]; !ok {
   283→		t.Errorf("SessionStart hook should have been installed")
   284→	}
   285→}
