   501→func readGeminiSettings(t *testing.T, tempDir string) GeminiSettings {
   502→	t.Helper()
   503→	settingsPath := filepath.Join(tempDir, ".gemini", "settings.json")
   504→	data, err := os.ReadFile(settingsPath)
   505→	if err != nil {
   506→		t.Fatalf("failed to read settings.json: %v", err)
