   516→func writeGeminiSettings(t *testing.T, tempDir, content string) {
   517→	t.Helper()
   518→	geminiDir := filepath.Join(tempDir, ".gemini")
   519→	if err := os.MkdirAll(geminiDir, 0o755); err != nil {
   520→		t.Fatalf("failed to create .gemini dir: %v", err)
   521→	}
   522→	settingsPath := filepath.Join(geminiDir, "settings.json")
   523→	if err := os.WriteFile(settingsPath, []byte(content), 0o644); err != nil {
   524→		t.Fatalf("failed to write settings.json: %v", err)
   525→	}
