   532→			for _, hook := range matcher.Hooks {
   533→				if hook.Command == expectedCommand {
   534→					return // Found
   535→				}
   536→			}
   537→		}
   538→	}
   539→	t.Errorf("hook with matcher=%q command=%q not found", expectedMatcher, expectedCommand)
